// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2, ERC20, SafeTransferLib} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    function testFuzz_property(
        bool isCall,
        uint256 premium,
        uint256 strike,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public {
        vm.warp(1_000);

        premium = bound(premium, 0, 1e30);
        strike = bound(strike, 0, 1e30);
        duration = bound(duration, 0, 9_999 days - 1);
        expiration = bound(expiration, 1_001, 1_001 + 3_650 days);

        // Adversarial/maker counterparty: an ERC1271 signer whose fallback accepts
        // the ERC20 transferFrom that fillOrder performs against it (baseAsset = maker).
        SigMaker maker = new SigMaker();

        PuttyV2.Order memory order;
        order.maker = address(maker);
        order.isCall = isCall;
        order.isLong = true;
        order.baseAsset = address(maker); // has code; its fallback makes transferFrom succeed
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new PuttyV2.ERC20Asset[](0);
        order.erc721Assets = new PuttyV2.ERC721Asset[](0);

        uint256[] memory floorAssetTokenIds = new uint256[](0);

        uint256 positionId = c.fillOrder(order, "", floorAssetTokenIds);

        // General rule: the taker's position id is derived from the OPPOSITE order
        // hash, so it can never equal the hash of the filled order itself.
        assertTrue(positionId != uint256(c.hashOrder(order)), "position id must be the opposite-order hash");
    }
}

contract SigMaker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }

    // Accepts the ERC20 transferFrom/transfer calldata dispatched to baseAsset with
    // empty returndata (SafeTransferLib treats empty returndata as success).
    fallback() external payable {}
}
